import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
for (const version of ['0.3.5','0.4.2']) {
  const source=execFileSync('tar',['-xOf',`.output/stabilization-checkpoints/auth-${version}.tgz`,'package/dist/matrx-oauth.js'],{encoding:'utf8'});
  const {createMatrxOAuth}=await import(`data:text/javascript;base64,${Buffer.from(source).toString('base64')}`);
  const store=new Map(), requests=[];
  const client=createMatrxOAuth({authUrl:'https://auth.invalid',clientId:'extension-guard',redirectUri:'https://extension.invalid/callback'},{storage:{getItem:async k=>store.get(k)??null,setItem:async(k,v)=>{store.set(k,v)},removeItem:async k=>{store.delete(k)}},openAuthorization:async()=>{throw Error('unexpected sign in')},fetch:async(url,options)=>{requests.push({url,method:options.method,authorization:options.headers.authorization,cleared:store.size===0});return new Response(null,{status:204})}});
  const token=`header.${Buffer.from(JSON.stringify({sub:'guard-person',exp:4102444800})).toString('base64url')}.signature`;
  await client.adoptTokens({accessToken:token,refreshToken:'guard-refresh',expiresAtMs:4102444800000});
  assert.notEqual(await client.getSession(),null);
  assert.deepEqual(await client.signOut(),{revoked:true});
  assert.equal(await client.getSession(),null);
  assert.deepEqual(requests,[{url:'https://auth.invalid/auth/v1/logout?scope=local',method:'POST',authorization:`Bearer ${token}`,cleared:true}]);
  assert.deepEqual(await client.signOut(),{revoked:null});
  assert.equal(requests.length,1);
  console.log(`auth ${version}: focused published-artifact local signOut probe PASS; one local POST after clearing; no-session no POST`);
}
